class Gradebook:
    def __init__(self) -> None:
        self._assignments = {}
        self._grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ("homework", "quiz"):
            raise ValueError(f"Invalid kind: {kind}")
        self._assignments[name] = {"weight": weight, "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the scale 2.0 to 5.0")
        if assignment not in self._assignments:
            raise KeyError(f"Unknown assignment: {assignment}")
        self._grades.setdefault(student, {})[assignment] = grade

    def average(self, student: str) -> float:
        student_grades = self._grades.get(student, {})

        quizzes = [
            (name, student_grades.get(name, 2.0))
            for name, info in self._assignments.items()
            if info["kind"] == "quiz"
        ]

        dropped_quiz = None
        if len(quizzes) > 1:
            dropped_quiz = min(quizzes, key=lambda x: x[1])[0]

        total_weight = 0.0
        weighted_sum = 0.0
        for name, info in self._assignments.items():
            if name == dropped_quiz:
                continue
            grade = student_grades.get(name, 2.0)
            weighted_sum += grade * info["weight"]
            total_weight += info["weight"]

        if total_weight == 0:
            return 0.0
        return weighted_sum / total_weight
